package net.officefloor.hq.app.holiday;

import java.sql.Date;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The holiday store: the dates on each sheet's list of holidays. */
@Repository
public class Holidays {

    private final JdbcTemplate jdbc;

    public Holidays(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's holidays (YYYY-MM-DD), earliest first. */
    public List<String> list(String sheetId) {
        return jdbc.query("SELECT holiday_date FROM holiday WHERE sheet_id = ? ORDER BY holiday_date",
                (rs, i) -> rs.getDate(1).toLocalDate().toString(), sheetId);
    }

    /** Whether the date is on the sheet's list. */
    public boolean contains(String sheetId, LocalDate date) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM holiday WHERE sheet_id = ? AND holiday_date = ?",
                Integer.class, sheetId, Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Adds the date to the sheet's list. */
    public void add(String sheetId, LocalDate date) {
        jdbc.update("INSERT INTO holiday (sheet_id, holiday_date) VALUES (?, ?)", sheetId, Date.valueOf(date));
    }

    /** A due-by moved past the sheet's holidays as they are now: the date when it is not a holiday, else the next day that is not. */
    public LocalDate dueBy(String sheetId, LocalDate date) {
        Set<LocalDate> holidays = new HashSet<>();
        jdbc.query("SELECT holiday_date FROM holiday WHERE sheet_id = ? AND holiday_date >= ?",
                rs -> { holidays.add(rs.getDate(1).toLocalDate()); }, sheetId, Date.valueOf(date));
        LocalDate due = date;
        while (holidays.contains(due)) {
            due = due.plusDays(1);
        }
        return due;
    }
}
-- The sheet's holidays: a claim's due-by fixed at creation that falls on one moves to the next day that is not.
CREATE TABLE holiday (
    sheet_id     VARCHAR(200) NOT NULL,
    holiday_date DATE         NOT NULL,
    PRIMARY KEY (sheet_id, holiday_date)
);
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Saves the split claim and adds the new OPEN claim with the split-off amount, the same date and note, the next
 *  number, opened by the user, its due-by fixed now from the terms in force on the date, split from the claim, and a
 *  late entry when the claim is one. */
public class SaveSplit {
    public void save(@Val ValidSplit request, @Val Claim claim, Claims claims, People people, Settings settings,
            ClaimNumbering numbering, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays, Out<ClaimSplit> split) {
        claims.save(claim);
        claims.bind(claim);
        String sheetId = claim.getSheetId();
        Person person = people.find(sheetId, claim.getPersonId());
        Claim into = claims.add(sheetId, person.getId(), request.amount(), claim.getDate(), claim.getNote(),
                holidays.dueBy(sheetId, claim.getDate().plusDays(settings.termsFor(sheetId, person.getTerms(), person.gradeOn(claim.getDate()), claim.getDate()))));
        into.setStatus(ClaimStatus.OPEN);
        into.setNumber(numbering.next(sheetId, into.getPeriodDate()));
        into.setOpenedBy(request.user());
        into.setSplitFrom(claim.getNumber());
        claims.save(into);
        claims.splitFrom(into);
        if (claim.isLateEntry()) {
            // A split is judged by the original claim alone: the new claim is a late entry as it is.
            claims.markLateEntry(into);
        }
        log.record(into, person, request.user());
        split.set(new ClaimSplit(into));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Adds a DRAFT claim dated the sheet's today, with an empty note, for the named person (name
 * compared as the person form compares it), first adding the person with grade A when no one on
 * the sheet has that name. One change: a refused claim leaves no new person behind.
 */
public class SaveQuickClaim {

    private static final String GRADE = "A";

    public void save(@PathVariable("sheetId") String sheetId, @Val ValidQuickClaim request, People people, Claims claims,
            Sheets sheets, Periods periods, Audit audit, @Val RollupFigures before, Rollup rollup,
            net.officefloor.hq.app.setting.Settings settings, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        LocalDate date = settings.claimDate(sheetId);
        Person person = people.findByName(sheetId, request.name());
        // Refuse before anything is written: the claim's period goes by the due-by it would be fixed with.
        LocalDate dueBy = holidays.dueBy(sheetId, date.plusDays(person != null
                ? settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date)
                : settings.termsFor(sheetId, GRADE, date)));
        if (periods.isClosed(sheetId, dueBy)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        RollupFigures beforeClaim = before;
        if (person == null) {
            person = people.add(sheetId, request.name(), GRADE);
            audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
                    + " name=" + person.getName() + " grade=" + person.getGrade());
            rollup.recordChanges(sheetId, request.user(), before);
            beforeClaim = rollup.figures(sheetId);
        }
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, "", dueBy);
        log.record(claim, person, request.user());
        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
        LateEntry.mark(claim, person, request.user(), claims, periods, audit);
        rollup.recordChanges(sheetId, request.user(), beforeClaim);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
